package com.siam.deviceinfo.widget;import android.appwidget.*;import android.content.*;import android.widget.*;import com.siam.deviceinfo.R;import com.siam.deviceinfo.helper.*;
public class DeviceWidget extends AppWidgetProvider {public void onUpdate(Context c,AppWidgetManager m,int[] ids){for(int id:ids){RemoteViews v=new RemoteViews(c.getPackageName(),R.layout.widget_device);java.util.Map<String,String>b=BatteryHelper.read(c);v.setTextViewText(R.id.widget_battery,"ব্যাটারি "+b.get("ব্যাটারি"));android.app.ActivityManager.MemoryInfo mi=new android.app.ActivityManager.MemoryInfo();((android.app.ActivityManager)c.getSystemService(Context.ACTIVITY_SERVICE)).getMemoryInfo(mi);v.setTextViewText(R.id.widget_ram,"খালি RAM "+DeviceInfoHelper.format(mi.availMem));m.updateAppWidget(id,v);}}}
